// Pipedrive on a personal API token: every operation of Pipedrive's API v2, and v1 for what v2 doesn't have yet.
// actions.json is generated by `bun scripts/openapi-actions.ts pipedrive`; deals, people, organizations, activities,
// leads, notes, products, pipelines, stages and users start automations by webhook (triggers.ts).
import type { OwnApp } from "../index";
import { type Api, call, specActions } from "../openapi";
import { events, receive, triggers, unwatch, wanted, watch } from "./triggers";

export const api: Api = {
  name: "Pipedrive",
  base: "https://api.pipedrive.com/api/v2",
  tokenHelp: "Pipedrive → Settings → Personal preferences → API",
  auth: (key) => ({ "x-api-token": key }),
  // Pipedrive says {"success": false, "error": "..."}; almost always with an error status, but not always
  failed: (body) => (body?.success === false ? String(body.error ?? "it didn't work") : undefined),
};

const ME = { method: "GET", base: "https://api.pipedrive.com/v1", path: "/users/me", query: [], headers: [] };

export const pipedrive: OwnApp = {
  app: "pipedrive",
  name: "Pipedrive",
  logo: "/logos/pipedrive.svg",
  keyField: {
    label: "API token",
    help: "In Pipedrive, open Settings → Personal preferences → API and copy your personal API token. Emplio can then see and change whatever your Pipedrive user can. No API tab? Ask your Pipedrive admin to turn on API access for you.",
    placeholder: "a1b2c3d4e5f6...",
  },
  async check(key) {
    const { data } = (await call(api, key, ME, {})) as { data: { name?: string; email?: string; company_name?: string } };
    const who = data.name || data.email || "Pipedrive";
    return data.company_name ? `${who} (${data.company_name})` : who;
  },
  push: {
    events,
    triggers,
    start: (key, connection) => watch(api, key, connection),
    stop: (key, id) => unwatch(api, key, id),
    receive,
    wanted,
  },
  actions: await specActions(new URL("./actions.json", import.meta.url), api),
};
